import AnalyticsOutlinedIcon from "@mui/icons-material/AnalyticsOutlined";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import {
	Box,
	ButtonBase,
	IconButton,
	Popover,
	Tooltip,
	Typography,
	useMediaQuery,
	useTheme,
} from "@mui/material";
import { format } from "date-fns";
import React from "react";
import DateRangeSelector from "../../../components/Common/DateRangeSelector/DateRangeSelector";
import { isValidDate } from "../../../utils/date/isValidDate";
import CategorySelector from "./CategorySelector";
import type { CategoryKey } from "./categoryMetadata";

export interface DashboardHeaderProps {
	startDate: Date;
	endDate: Date;
	onStartDateChange: (date: Date | null) => void;
	onEndDateChange: (date: Date | null) => void;
	selectedCategory: CategoryKey;
	onSelectCategory: (key: CategoryKey) => void;
	showTips: boolean;
	onToggleTips: () => void;
}

const DashboardHeader: React.FC<DashboardHeaderProps> = ({
	startDate,
	endDate,
	onStartDateChange,
	onEndDateChange,
	selectedCategory,
	onSelectCategory,
	showTips,
	onToggleTips,
}) => {
	const theme = useTheme();
	const isNarrow = useMediaQuery(theme.breakpoints.down("sm"));
	const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

	const open = Boolean(anchorEl);

	const handleOpen = (e: React.MouseEvent<HTMLElement>) =>
		setAnchorEl(e.currentTarget);
	const handleClose = () => setAnchorEl(null);

	// date-fns throws on a date it cannot format, and a throw here takes the whole
	// application down with it. A missing label is a far smaller loss than that.
	const formatDate = (d: Date) =>
		isValidDate(d) ? format(d, "dd MMM yyyy") : "—";

	return (
		<Box
			sx={{
				width: "100%",
				p: 1,
				mb: 1,
			}}
		>
			<Box
				sx={{
					display: "flex",
					alignItems: "center",
					justifyContent: "space-between",
					mb: 1,
				}}
			>
				<CategorySelector
					selectedCategory={selectedCategory}
					onSelectCategory={onSelectCategory}
				/>
				<Tooltip title={showTips ? "Hide tips" : "Show tips"}>
					<IconButton
						size="small"
						onClick={onToggleTips}
						color={showTips ? "primary" : "default"}
						aria-pressed={showTips}
						data-testid="metrics-tips-toggle"
					>
						<AnalyticsOutlinedIcon fontSize="small" />
					</IconButton>
				</Tooltip>
			</Box>

			<Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
				{!isNarrow && (
					<Typography
						variant="subtitle2"
						color="text.secondary"
						sx={{ mr: 0.5 }}
					>
						Metrics shown for:
					</Typography>
				)}

				<Tooltip title={isNarrow ? "Metrics shown for" : ""}>
					<ButtonBase
						data-testid="dashboard-date-range-toggle"
						onClick={handleOpen}
						sx={{
							display: "inline-flex",
							alignItems: "center",
							gap: 1,
							px: 1,
							py: 0.25,
							borderRadius: 1,
							transition: "background-color 150ms",
							"&:hover": { backgroundColor: theme.palette.action.hover },
						}}
					>
						<CalendarMonthIcon color="action" fontSize="small" />
						{!isNarrow && (
							<Typography
								variant="body2"
								color="text.primary"
								sx={{ fontWeight: 500 }}
							>
								{` ${formatDate(startDate)} → ${formatDate(endDate)}`}
							</Typography>
						)}
					</ButtonBase>
				</Tooltip>
			</Box>

			<Popover
				open={open}
				anchorEl={anchorEl}
				onClose={handleClose}
				anchorOrigin={{ vertical: "bottom", horizontal: "left" }}
				transformOrigin={{ vertical: "top", horizontal: "left" }}
				disableEnforceFocus
				disablePortal
			>
				<DateRangeSelector
					startDate={startDate}
					endDate={endDate}
					onStartDateChange={onStartDateChange}
					onEndDateChange={onEndDateChange}
				/>
			</Popover>
		</Box>
	);
};

export default DashboardHeader;

