import { fireEvent, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { DashboardHeaderProps } from "./DashboardHeader";

vi.mock(
	"../../../components/Common/DateRangeSelector/DateRangeSelector",
	() => ({
		default: (props: {
			onStartDateChange: (d: Date) => void;
			onEndDateChange: (d: Date) => void;
		}) => (
			<div data-testid="date-range-selector">
				<button
					type="button"
					data-testid="change-start-date"
					onClick={() => props.onStartDateChange(new Date("2020-01-01"))}
				>
					Change Start
				</button>
				<button
					type="button"
					data-testid="change-end-date"
					onClick={() => props.onEndDateChange(new Date("2020-01-02"))}
				>
					Change End
				</button>
			</div>
		),
	}),
);

vi.mock("./CategorySelector", () => ({
	default: ({
		selectedCategory,
		onSelectCategory,
	}: {
		selectedCategory: string;
		onSelectCategory: (key: string) => void;
	}) => (
		<div data-testid="category-selector">
			<span data-testid="selected-category">{selectedCategory}</span>
			<button
				type="button"
				data-testid="select-category"
				onClick={() => onSelectCategory("portfolio")}
			>
				Switch
			</button>
		</div>
	),
}));

// MUI reads matchMedia through useMediaQuery, and jsdom does not provide it.
function setMatchMedia(matches: boolean) {
	Object.defineProperty(globalThis, "matchMedia", {
		writable: true,
		value: (query: string) => ({
			matches,
			media: query,
			onchange: null,
			addListener: () => {},
			removeListener: () => {},
			addEventListener: () => {},
			removeEventListener: () => {},
			dispatchEvent: () => false,
		}),
	});
}

const renderHeader = async (overrides: Partial<DashboardHeaderProps> = {}) => {
	const { default: DashboardHeader } = await import("./DashboardHeader");

	render(
		<DashboardHeader
			startDate={new Date(2025, 6, 15)}
			endDate={new Date(2025, 7, 14)}
			onStartDateChange={vi.fn()}
			onEndDateChange={vi.fn()}
			selectedCategory="flow-overview"
			onSelectCategory={vi.fn()}
			showTips={true}
			onToggleTips={vi.fn()}
			{...overrides}
		/>,
	);
};

describe("DashboardHeader", () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	afterEach(() => {
		setMatchMedia(false);
	});

	// Drives a popover through several user interactions, which costs a few seconds on its own and
	// more when the suite is busy. The default five seconds left no headroom, so this test went red
	// whenever tests were added elsewhere in the suite.
	it("shows label and formatted date range and opens popover which calls handlers", {
		timeout: 20000,
	}, async () => {
		setMatchMedia(false);

		const onStartDateChange = vi.fn();
		const onEndDateChange = vi.fn();

		await renderHeader({ onStartDateChange, onEndDateChange });

		expect(screen.getByText("Metrics shown for:")).toBeInTheDocument();

		expect(
			screen.getByText(/15 Jul 2025\s*→\s*14 Aug 2025/),
		).toBeInTheDocument();

		fireEvent.click(screen.getByTestId("dashboard-date-range-toggle"));

		expect(
			await screen.findByTestId("date-range-selector"),
		).toBeInTheDocument();

		fireEvent.click(screen.getByTestId("change-start-date"));
		expect(onStartDateChange).toHaveBeenCalled();

		fireEvent.click(screen.getByTestId("change-end-date"));
		expect(onEndDateChange).toHaveBeenCalled();
	});

	it("hides the label on narrow screens but keeps the toggle", async () => {
		setMatchMedia(true);

		await renderHeader();

		expect(screen.queryByText("Metrics shown for:")).toBeNull();

		expect(
			screen.getByTestId("dashboard-date-range-toggle"),
		).toBeInTheDocument();
	});

	it("does not expose edit toggle or reset layout controls", async () => {
		setMatchMedia(false);

		await renderHeader();

		expect(
			screen.queryByTestId("dashboard-edit-toggle"),
		).not.toBeInTheDocument();
		expect(
			screen.queryByTestId("dashboard-reset-layout"),
		).not.toBeInTheDocument();
	});

	it("renders category selector with the selected category", async () => {
		setMatchMedia(false);

		await renderHeader({ selectedCategory: "predictability" });

		expect(screen.getByTestId("category-selector")).toBeInTheDocument();
		expect(screen.getByTestId("selected-category")).toHaveTextContent(
			"predictability",
		);
	});

	it("renders a placeholder for an unusable date and leaves the other one formatted", async () => {
		setMatchMedia(false);

		await renderHeader({ startDate: new Date(Number.NaN) });

		expect(screen.getByText(/—\s*→\s*14 Aug 2025/)).toBeInTheDocument();
	});

	it("keeps the header mounted when both dates are unusable", async () => {
		setMatchMedia(false);

		await renderHeader({
			startDate: new Date(Number.NaN),
			endDate: new Date(Number.NaN),
		});

		expect(screen.getByText(/—\s*→\s*—/)).toBeInTheDocument();
		expect(
			screen.getByTestId("dashboard-date-range-toggle"),
		).toBeInTheDocument();
	});

	it("renders tips toggle and calls onToggleTips when clicked", async () => {
		setMatchMedia(false);

		const onToggleTips = vi.fn();

		await renderHeader({ onToggleTips });

		const toggle = screen.getByTestId("metrics-tips-toggle");
		expect(toggle).toBeInTheDocument();
		fireEvent.click(toggle);
		expect(onToggleTips).toHaveBeenCalled();
	});
});

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { useState } from "react";
import { describe, expect, it, vi } from "vitest";
import DashboardHeader from "./DashboardHeader";

/**
 * The sibling test file stubs the date range selector away, so it can never see
 * what happens when a real date field is torn down by a real popover. This file
 * mounts both for real, because that teardown is where a typed date can vanish:
 * the popover removes its children on close and the browser never reports that
 * the field lost focus, so a user types a date, clicks away, and the dashboard
 * silently keeps the old range.
 *
 * Two things to know if this file ever breaks after a picker upgrade. The field
 * renders one `role="spinbutton"` per section, addressed by its aria-label
 * ("Day", "Month", "Year"); `getAllByRole("textbox")` finds nothing at all. And
 * each section is filled by its own label rather than by typing straight
 * through, so the assertions do not depend on the order the machine's locale
 * happens to put day, month and year in.
 */

const START_DATE = new Date(2026, 6, 15);
const END_DATE = new Date(2026, 7, 15);

const renderHeader = () => {
	const onStartDateChange = vi.fn();

	const Harness = () => {
		const [startDate, setStartDate] = useState(START_DATE);

		return (
			<DashboardHeader
				startDate={startDate}
				endDate={END_DATE}
				onStartDateChange={(date) => {
					onStartDateChange(date);
					if (date) {
						setStartDate(date);
					}
				}}
				onEndDateChange={vi.fn()}
				selectedCategory="flow-overview"
				onSelectCategory={vi.fn()}
				showTips={false}
				onToggleTips={vi.fn()}
			/>
		);
	};

	render(<Harness />);

	return { onStartDateChange, user: userEvent.setup() };
};

// `hidden: true` is not optional here. The popover renders in place instead of
// in a portal, so MUI marks everything around it — including the element the
// test renders into — as hidden from screen readers, and a plain role query
// then finds none of the date sections.
const startSection = (label: string) =>
	screen.getAllByRole("spinbutton", { name: label, hidden: true })[0];

const openDateRange = async (user: ReturnType<typeof userEvent.setup>) => {
	await user.click(screen.getByTestId("dashboard-date-range-toggle"));
	await screen.findByText("Start Date");
};

const typeStartDate = async (user: ReturnType<typeof userEvent.setup>) => {
	await user.click(startSection("Day"));
	await user.keyboard("05");
	await user.click(startSection("Month"));
	await user.keyboard("07");
	await user.click(startSection("Year"));
	await user.keyboard("2026");
};

const clickBackdrop = async (user: ReturnType<typeof userEvent.setup>) => {
	const backdrop = document.querySelector(".MuiBackdrop-root");
	if (!backdrop) {
		throw new Error("the popover rendered without a backdrop to click");
	}

	await user.click(backdrop);
};

describe("DashboardHeader date range popover", () => {
	it("keeps a date typed into the popover after Escape closes it", async () => {
		const { user, onStartDateChange } = renderHeader();

		await openDateRange(user);
		await typeStartDate(user);
		await user.keyboard("{Escape}");

		await waitFor(() =>
			expect(onStartDateChange).toHaveBeenCalledWith(new Date(2026, 6, 5)),
		);
		expect(onStartDateChange).toHaveBeenCalledTimes(1);
	});

	it("keeps a date typed into the popover after a click on the backdrop", async () => {
		const { user, onStartDateChange } = renderHeader();

		await openDateRange(user);
		await typeStartDate(user);
		await clickBackdrop(user);

		await waitFor(() =>
			expect(onStartDateChange).toHaveBeenCalledWith(new Date(2026, 6, 5)),
		);
		expect(onStartDateChange).toHaveBeenCalledTimes(1);
	});

	it("shows the date typed into the popover once it is closed", async () => {
		const { user } = renderHeader();

		await openDateRange(user);
		await typeStartDate(user);
		await user.keyboard("{Escape}");

		await screen.findByText(/05 Jul 2026/);
	});
});

